"""One-time, evidence-based family shortlist; does not replace the catalogue."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
p = ROOT / 'data/catalog.json'
d = json.loads(p.read_text())
assert d['completeness_audit']['version'] == 26 and len(d['events']) == 1223
assert 'top_picks' not in d
picks = []

def add(id, category, title, targets, place, label, why, facts, gate, action,
        mat='candidate', osc='candidate', horizon='now', tier='main', sources=()):
    picks.append(dict(id=id, category=category, title=title, target_ids=targets,
        place=place, label=label, why=why, facts=facts, gate=gate, next_action=action,
        fit={'mat':mat,'osc':osc}, horizon=horizon, tier=tier,
        sources=[dict(title=t,url=u) for t,u in sources]))

